1	/**
2	 * Status store — holds integration health check results.
3	 * Populated once on extension load from GET /api/status.
4	 * Resets on every extension load.
5	 */
6	
7	export interface IntegrationStatus {
8	  name: string;
9	  status: 'healthy' | 'unavailable';
10	  latency_ms: number | null;
11	  error: string | null;
12	}
13	
14	class StatusStore {
15	  integrations = $state<IntegrationStatus[]>([]);
16	  loading = $state(false);
17	  error = $state<string | null>(null);
18	}
19	
20	export const statusStore = new StatusStore();
21

1	<script lang="ts">
2	  import { statusStore } from '../stores/status.svelte';
3	
4	  const DISPLAY_NAMES: Record<string, string> = {
5	    smartsheet: 'Smartsheet',
6	    google_calendar: 'Google Calendar',
7	    google_docs: 'Google Docs',
8	    tableau_data: 'Tableau Data',
9	  };
10	</script>
11	
12	<div class="status-bar">
13	  {#if statusStore.loading}
14	    <p class="status-checking">Checking integrations…</p>
15	  {:else if statusStore.error}
16	    <p class="status-bar-error">Status check failed: {statusStore.error}</p>
17	  {:else}
18	    <ul class="status-list">
19	      {#each statusStore.integrations as integration (integration.name)}
20	        <li class="status-item status-{integration.status}">
21	          <span class="status-indicator" aria-hidden="true">
22	            {integration.status === 'healthy' ? '●' : '○'}
23	          </span>
24	          <span class="status-name">
25	            {DISPLAY_NAMES[integration.name] ?? integration.name}
26	          </span>
27	          {#if integration.status === 'unavailable' && integration.error}
28	            <span class="status-error-msg">— {integration.error}</span>
29	          {/if}
30	        </li>
31	      {/each}
32	    </ul>
33	  {/if}
34	</div>
35	
