1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { initializeExtension, getTableauUserId } from './lib/tableau';
4	  import { apiFetch, ApiError } from './lib/api';
5	  import { sessionStore } from './stores/session.svelte';
6	  import { statusStore } from './stores/status.svelte';
7	  import StatusBar from './components/StatusBar.svelte';
8	
9	  type AppStatus = 'loading' | 'ready' | 'error';
10	
11	  let appStatus = $state<AppStatus>('loading');
12	  let errorMessage = $state('');
13	
14	  onMount(async () => {
15	    try {
16	      // Step 1: Initialize Tableau runtime
17	      await initializeExtension();
18	
19	      // Step 2: Get Tableau user identity
20	      const tableauUserId = getTableauUserId();
21	      sessionStore.tableauUserId = tableauUserId;
22	
23	      // Step 3: Create backend session
24	      const sessionResponse = await apiFetch<{
25	        data: { session_id: string; started_at: string };
26	      }>('/api/sessions', {
27	        method: 'POST',
28	        body: JSON.stringify({ tableau_user_id: tableauUserId }),
29	      });
30	      sessionStore.sessionId = sessionResponse.data.session_id;
31	
32	      // Step 4: Fetch integration statuses
33	      statusStore.loading = true;
34	      const statusResponse = await apiFetch<{
35	        data: { integrations: Array<{ name: string; status: string; latency_ms: number | null; error: string | null }> };
36	      }>('/api/status', {
37	        headers: { 'X-Autom9-Session': sessionStore.sessionId },
38	      });
39	
40	      statusStore.integrations = statusResponse.data.integrations.map((i) => ({
41	        name: i.name,
42	        status: i.status as 'healthy' | 'unavailable',
43	        latency_ms: i.latency_ms,
44	        error: i.error,
45	      }));
46	      statusStore.loading = false;
47	
48	      appStatus = 'ready';
49	    } catch (err) {
50	      statusStore.loading = false;
51	      if (err instanceof ApiError) {
52	        // Backend reachable but returned error — show specific message
53	        errorMessage = err.message;
54	      } else {
55	        errorMessage = err instanceof Error ? err.message : 'Extension failed to initialize';
56	      }
57	      appStatus = 'error';
58	    }
59	  });
60	</script>
61	
62	{#if appStatus === 'loading'}
63	  <div class="autom9-loading">
64	    <p>Loading autom9…</p>
65	  </div>
66	{:else if appStatus === 'error'}
67	  <div class="autom9-error">
68	    <p><strong>autom9 failed to load</strong></p>
69	    <p>{errorMessage}</p>
70	  </div>
71	{:else}
72	  <div class="autom9-shell">
73	    <StatusBar />
74	    <!-- Chat panel and data panel added in Epic 3 stories -->
75	  </div>
76	{/if}
77	
78	<style>
79	  .autom9-loading,
80	  .autom9-error,
81	  .autom9-shell {
82	    font-family: sans-serif;
83	    min-height: 100vh;
84	  }
85	  .autom9-loading {
86	    padding: 1rem;
87	  }
88	  .autom9-error {
89	    color: #c00;
90	    padding: 1rem;
91	  }
92	</style>
